import json, sys
baseline = json.load(open('baseline-packages.json'))
after = json.load(sys.stdin)

def extract(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-2]
        for fw in proj['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                result.setdefault(name, {})[pkg['id']] = pkg['resolvedVersion']
    return result

b, a = extract(baseline), extract(after)
match = b == a
print('Package versions match baseline:', match)
if not match:
    for proj in set(list(b.keys()) + list(a.keys())):
        for pkg in set(list(b.get(proj,{}).keys()) + list(a.get(proj,{}).keys())):
            bv = b.get(proj,{}).get(pkg)
            av = a.get(proj,{}).get(pkg)
            if bv != av:
                print(f'  DIFF {proj}/{pkg}: {bv} -> {av}')
"

